        private final List<Entry> entries;
        private final List<String> unownedFiles;

        private IntegrityReport(List<Entry> entries, List<String> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        private boolean isClean() {
            return entries.stream().noneMatch(entry -> entry.broken || entry.resolvedViolations || entry.shared
                    || entry.misplaced || entry.colliding || entry.occupied) && unownedFiles.isEmpty();
        }

        private String message(File folder) {
            StringBuilder result = new StringBuilder("Violation store integrity check failed for ")
                    .append(folder.getAbsolutePath()).append(":");
            appendEntries(result, "broken", entry -> entry.broken);
            appendEntries(result, "resolved", entry -> entry.resolvedViolations);
            appendEntries(result, "shared", entry -> entry.shared);
            appendEntries(result, "misplaced", entry -> entry.misplaced);
            appendEntries(result, "colliding", entry -> entry.colliding);
            appendEntries(result, "occupied", entry -> entry.occupied);
            if (!unownedFiles.isEmpty()) {
                result.append("\nUnowned files:");
                for (String file : unownedFiles) {
                    result.append("\n  ").append(file);
                }
            }
            return result.toString();
        }

        private void appendEntries(StringBuilder result, String condition, EntryPredicate predicate) {
            List<Entry> matching = entries.stream().filter(predicate::matches)
                    .sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
            if (!matching.isEmpty()) {
                result.append("\n").append(capitalize(condition)).append(" entries:");
                for (Entry entry : matching) {
                    result.append("\n  ").append(entry.description).append(" -> ").append(entry.fileName);
                }
            }
        }

        private String capitalize(String value) {
