    }

    @Test
    public void stores_violations_with_line_breaks() {
        List<String> expected = ImmutableList.of(String.format("first with%nlinebreak"), String.format("second with%nlinebreak"));

        store.save(defaultRule(), expected);

        List<String> violations = store.getViolations(defaultRule());
        assertThat(violations).as("stored violations").containsExactlyElementsOf(expected);
    }

    @Test
    public void description_file_names_are_safe_deterministic_and_distinct() throws IOException {
        ViolationStore descriptionStore = new TextFileBasedViolationStore();
        Properties properties = defaultStoreProperties();
        properties.setProperty("default.fileNames", "description");
        descriptionStore.initialize(properties);

        ArchRule first = rule("first description");
        ArchRule second = rule("second description");
        descriptionStore.save(first, ImmutableList.of("first"));
        descriptionStore.save(second, ImmutableList.of("second"));

        Properties index = readProperties(new File(configuredFolder, "stored.rules"));
        String firstName = index.getProperty(first.getDescription());
        String secondName = index.getProperty(second.getDescription());
        assertThat(firstName).contains("first").matches("[A-Za-z0-9_-]{1,200}").isNotEqualTo("stored.rules");
        assertThat(secondName).contains("second").isNotEqualTo(firstName);
    }

    @Test
    public void preserves_carriage_returns_inside_violations_but_not_as_empty_file_content() throws IOException {
        String violation = "before\rinside";
        store.save(defaultRule(), ImmutableList.of(violation));
        assertThat(store.getViolations(defaultRule())).containsExactly(violation);

        Properties index = readProperties(new File(configuredFolder, "stored.rules"));
        File violationFile = new File(configuredFolder, index.getProperty(defaultRule().getDescription()));
        Files.write(violationFile.toPath(), "\r".getBytes(UTF_8));

        ViolationStore repairStore = new TextFileBasedViolationStore();
        Properties repairProperties = defaultStoreProperties();
        repairProperties.setProperty("default.integrity", "repair");
        repairStore.initialize(repairProperties);
        assertThat(readProperties(new File(configuredFolder, "stored.rules"))).doesNotContainKey(defaultRule().getDescription());
        assertThat(violationFile).doesNotExist();
    }

    private Properties readProperties(File file) throws IOException {
        Properties properties = new Properties();
        try (FileInputStream inputStream = new FileInputStream(file)) {
            properties.load(inputStream);
        }
        return properties;
    }

    private Properties defaultStoreProperties() {
        return propertiesOf(
                "default.path", configuredFolder.getAbsolutePath(),
                "default.allowStoreCreation", String.valueOf(true));
    }

    private Properties propertiesOf(String... keyValuePairs) {
        Properties result = new Properties();
        LinkedList<String> keyValues = new LinkedList<>(asList(keyValuePairs));
        while (!keyValues.isEmpty()) {
            result.setProperty(keyValues.poll(), keyValues.poll());
        }
        return result;
    }

    private ArchRule defaultRule() {
        return rule("default rule");
    }

    private ArchRule rule(String description) {
        return classes().should().bePublic().as(description);
    }
