+        if (INTEGRITY_IGNORE.equals(value)) {
+            return IntegrityMode.IGNORE;
+        }
+        if (INTEGRITY_REPAIR.equals(value)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(value)) {
+            return IntegrityMode.FAIL;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid value for %s: '%s' (accepted values: %s, %s, %s)",
+                INTEGRITY_PROPERTY_NAME, value, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE));
+    }
+
+    private void configureNameStrategy(Properties properties) {
+        if (strategyWasGivenToConstructor) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot configure %s when a %s was supplied to the constructor",
+                        FILE_NAMES_PROPERTY_NAME, RuleViolationFileNameStrategy.class.getSimpleName()));
+            }
+            ruleViolationFileNameStrategy = constructorStrategy;
+            nameMode = NameMode.CUSTOM;
+            return;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            ruleViolationFileNameStrategy = constructorStrategy;
+            nameMode = NameMode.RANDOM;
+        } else if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::descriptionBasedFileName;
+            nameMode = NameMode.DESCRIPTION;
+        } else {
+            ruleViolationFileNameStrategy = instantiateStrategy(configured);
+            nameMode = NameMode.CUSTOM;
+        }
+    }
+
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> strategyClass = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new ClassCastException(strategyClass.getName());
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
+        }
+    }
+
+    private void initializeStore(StoreState state) {
+        File storedRulesFile = state.index.toFile();
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
+
+        boolean folderExists = state.folder.exists();
+        boolean indexExists = Files.exists(state.index, LinkOption.NOFOLLOW_LINKS);
+        if (!folderExists) {
+            if (!storeCreationAllowed || integrityMode == IntegrityMode.FAIL) {
+                rejectMissingStore(storedRulesFile);
+            }
+            if (!state.folder.mkdirs() && !state.folder.isDirectory()) {
+                throw new StoreInitializationFailedException(String.format("Cannot create rule store at %s", state.folder));
+            }
+            indexExists = false;
+        } else if (!state.folder.isDirectory()) {
+            throw new StoreInitializationFailedException(String.format("Store path is not a folder: %s", state.folder));
+        }
+
+        if (!indexExists) {
+            if (!storeCreationAllowed) {
+                rejectMissingStore(storedRulesFile);
+            }
+            if (integrityMode == IntegrityMode.FAIL) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Integrity check failed for %s: missing index file", storedRulesFile.getAbsolutePath()));
+            }
+            state.properties = new Properties();
+            writePropertiesAtomically(state, state.properties);
+        } else if (!Files.isRegularFile(state.index, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The index file must be a regular file directly in the store folder: %s", storedRulesFile.getAbsolutePath()));
+        } else {
+            state.properties = loadProperties(state.index.toFile());
+        }
+
+        if (integrityMode == IntegrityMode.IGNORE) {
+            return;
+        }
+
+        IntegrityReport report = inspect(state);
+        if (integrityMode == IntegrityMode.FAIL && !report.isClean()) {
+            throw new StoreInitializationFailedException(report.message(state.folder));
+        }
+        if (integrityMode == IntegrityMode.REPAIR) {
+            boolean changed = repair(state, report);
+            if (changed) {
+                writePropertiesAtomically(state, state.properties);
+            }
+        }
+    }
+
+    private void rejectMissingStore(File storedRulesFile) {
+        throw new StoreInitializationFailedException(String.format(
+                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+    }
+
+    private Properties loadProperties(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (requiredStore().lock) {
+            return requiredStore().properties.containsKey(normalize(rule.getDescription()));
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        StoreState state = requiredStore();
+        synchronized (state.lock) {
+            log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+            if (!storeUpdateAllowed) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+            }
+
+            String description = normalize(rule.getDescription());
+            String existingFileName = state.properties.getProperty(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && existingFileName != null) {
+                forgetResolvedRule(state, description, existingFileName);
+            } else if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                // In repair mode an unknown rule with no violations is not stored.
+                return;
+            } else if (existingFileName == null) {
+                String newFileName = requiredFileName(rule.getDescription(), false);
+                saveNewRule(state, description, newFileName, violations);
+            } else {
+                saveExistingRule(state, existingFileName, violations);
+            }
+        }
+    }
+
+    private void forgetResolvedRule(StoreState state, String description, String fileName) {
+        Path entryPath = state.folder.toPath().resolve(fileName).normalize();
+        ResolvedFile resolved = resolveEntryFile(state, fileName);
+        if (resolved != null && isSharedByAnotherEntry(state, description, resolved)) {
+            Properties changed = copyOf(state.properties);
+            changed.remove(description);
+            writePropertiesAtomically(state, changed);
+            state.properties = changed;
+            return;
+        }
+        if (pathExists(entryPath) && resolved == null) {
+            throw new StoreUpdateFailedException(new IOException("Cannot safely delete " + entryPath));
+        }
+        if (resolved != null) {
+            deleteResolvedFile(resolved);
+        }
+        Properties changed = copyOf(state.properties);
+        changed.remove(description);
+        try {
+            writePropertiesAtomically(state, changed);
+        } catch (RuntimeException e) {
+            state.properties = copyOf(state.properties);
+            throw e;
+        }
+        state.properties = changed;
+    }
+
+    private void saveNewRule(StoreState state, String description, String fileName, List<String> violations) {
+        Path target = safeDirectPath(state, fileName);
+        if (pathExists(target) || state.properties.containsValue(fileName)) {
+            throw new StoreUpdateFailedException(new IOException("Refusing to overwrite an existing store file " + target));
+        }
+        writeNewFileAndIndex(state, description, fileName, target, violations);
+    }
+
+    private void saveExistingRule(StoreState state, String fileName, List<String> violations) {
+        Path target = writableEntryTarget(state, fileName);
+        writeFileAtomically(target, violations, true, state);
+    }
+
+    private void writeNewFileAndIndex(StoreState state, String description, String fileName, Path target, List<String> violations) {
+        Path temporary = null;
+        boolean moved = false;
+        try {
+            temporary = writeTemporaryFile(state, violations);
+            move(temporary, target, false);
+            moved = true;
+            Properties changed = copyOf(state.properties);
+            changed.setProperty(description, fileName);
+            try {
+                writePropertiesAtomically(state, changed);
+            } catch (RuntimeException e) {
+                if (moved) {
+                    deleteIfExists(target);
+                }
+                throw e;
+            }
+            state.properties = changed;
+        } catch (IOException e) {
+            if (temporary != null) {
+                deleteIfExists(temporary);
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void writeFileAtomically(Path target, List<String> violations, boolean replace, StoreState state) {
+        Path temporary = null;
+        try {
+            temporary = writeTemporaryFile(state, violations);
+            move(temporary, target, replace);
+        } catch (IOException e) {
+            if (temporary != null) {
+                deleteIfExists(temporary);
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private Path writeTemporaryFile(StoreState state, List<String> violations) throws IOException {
+        Path temporary = Files.createTempFile(state.folder.toPath(), ".archunit-store-", ".tmp");
+        try {
+            Files.write(temporary, encodedViolations(violations).getBytes(UTF_8));
+            return temporary;
+        } catch (IOException e) {
+            deleteIfExists(temporary);
+            throw e;
+        }
+    }
+
+    private void move(Path source, Path target, boolean replace) throws IOException {
+        try {
+            if (replace) {
+                Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+            } else {
+                Files.move(source, target, StandardCopyOption.ATOMIC_MOVE);
+            }
+        } catch (java.nio.file.AtomicMoveNotSupportedException e) {
+            if (replace) {
+                Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
+            } else {
+                Files.move(source, target);
+            }
+        }
+    }
+
+    private String encodedViolations(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        return builder.toString();
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        StoreState state = requiredStore();
+        synchronized (state.lock) {
+            String ruleDetailsFileName = state.properties.getProperty(normalize(rule.getDescription()));
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            ResolvedFile resolved = resolveEntryFile(state, ruleDetailsFileName);
+            if (resolved == null) {
+                throw new StoreReadException(new IOException("Store entry does not name a regular file directly in the store folder"));
+            }
+            List<String> result = readLines(resolved.path);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path file) {
+        String violationsText;
+        try {
+            violationsText = new String(toByteArray(file.toFile()), UTF_8);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+        if (violationsText.length() == 0 || onlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        violationsText = ensureUnixLineBreaks(violationsText);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private boolean onlyLineBreaks(String text) {
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character != '\r' && character != '\n') {
+                return false;
+            }
+        }
+        return text.length() > 0;
+    }
+
+    private String requiredFileName(String description, boolean initialization) {
+        String fileName;
+        try {
+            fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            if (initialization) {
+                throw new StoreInitializationFailedException("Could not derive a rule violation file name", e);
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+        if (fileName == null || fileName.trim().isEmpty()) {
+            RuntimeException exception = initialization
+                    ? new StoreInitializationFailedException("Rule violation file name strategy returned no name")
+                    : new StoreUpdateFailedException("Rule violation file name strategy returned no name");
+            throw exception;
+        }
+        return fileName;
+    }
+
+    private StoreState requiredStore() {
+        if (store == null) {
+            throw new IllegalStateException("Violation store has not been initialized");
+        }
+        return store;
+    }
+
+    private String normalize(String value) {
+        return ensureUnixLineBreaks(value);
+    }
+
+    private static String descriptionBasedFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String selectedWord = null;
+        while (matcher.find()) {
+            String word = matcher.group(1);
+            if (selectedWord == null || word.length() >= selectedWord.length()) {
+                selectedWord = word;
+            }
+        }
+        if (selectedWord == null) {
+            selectedWord = sanitize(description);
+        }
+        if (selectedWord.isEmpty()) {
+            selectedWord = "rule";
+        }
+        String hash = sha256(description);
+        String result = selectedWord + "-" + hash;
+        if (!BUILT_IN_FILE_NAME_PATTERN.matcher(result).matches() || result.length() > 200) {
+            result = "rule-" + hash;
+        }
+        if (STORED_RULES_FILE_NAME.equals(result)) {
+            result = "rule-" + hash;
+        }
+        return result;
+    }
+
+    private static String sanitize(String input) {
+        StringBuilder result = new StringBuilder();
+        boolean separator = false;
+        for (int i = 0; i < input.length(); i++) {
+            char character = input.charAt(i);
+            if ((character >= 'A' && character <= 'Z') || (character >= 'a' && character <= 'z')
+                    || (character >= '0' && character <= '9')) {
+                result.append(character);
+                separator = false;
+            } else if (!separator) {
+                result.append('_');
+                separator = true;
+            }
+        }
+        while (result.length() > 0 && result.charAt(result.length() - 1) == '_') {
+            result.deleteCharAt(result.length() - 1);
+        }
+        return result.toString();
+    }
+
+    private static String sha256(String input) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder();
+            for (byte value : digest) {
+                result.append(String.format("%02x", value & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private IntegrityReport inspect(StoreState state) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : state.properties.stringPropertyNames()) {
+            String fileName = state.properties.getProperty(description);
+            entries.add(new Entry(description, fileName));
+        }
+
+        Map<String, Integer> recordedNameCounts = new HashMap<>();
+        Map<String, Integer> derivedNameCounts = new HashMap<>();
+        for (Entry entry : entries) {
+            recordedNameCounts.put(entry.fileName, recordedNameCounts.getOrDefault(entry.fileName, 0) + 1);
+            if (nameMode != NameMode.RANDOM) {
+                entry.derivedName = requiredFileName(entry.description, true);
+                derivedNameCounts.put(entry.derivedName, derivedNameCounts.getOrDefault(entry.derivedName, 0) + 1);
+            }
+            entry.resolvedFile = resolveEntryFile(state, entry.fileName);
+            entry.broken = entry.resolvedFile == null;
+            if (!entry.broken) {
+                entry.resolvedViolations = readLines(entry.resolvedFile.path).isEmpty();
+            }
+        }
+
+        for (Entry entry : entries) {
+            entry.shared = recordedNameCounts.get(entry.fileName) > 1;
+            if (!entry.shared && entry.resolvedFile != null) {
+                for (Entry other : entries) {
+                    if (entry != other && other.resolvedFile != null && sameFile(entry.resolvedFile, other.resolvedFile)) {
+                        entry.shared = true;
+                        break;
+                    }
+                }
+            }
+            if (entry.derivedName != null) {
+                entry.misplaced = !entry.fileName.equals(entry.derivedName);
+                entry.colliding = derivedNameCounts.get(entry.derivedName) > 1;
+                if (entry.misplaced) {
+                    Path derivedPath = state.folder.toPath().resolve(entry.derivedName).normalize();
+                    boolean recordedByAnother = false;
+                    for (Entry other : entries) {
+                        if (other != entry && entry.derivedName.equals(other.fileName)) {
+                            recordedByAnother = true;
+                            break;
+                        }
+                    }
+                    entry.occupied = !isDirectPath(state, derivedPath)
+                            || pathExists(derivedPath)
+                            || recordedByAnother;
+                }
+            }
+        }
+
+        Set<String> ownedFiles = new HashSet<>();
+        for (Entry entry : entries) {
+            if (entry.resolvedFile != null) {
+                ownedFiles.add(fileIdentity(entry.resolvedFile.path));
+            }
+        }
+        List<String> unownedFiles = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(state.folder.toPath())) {
+            for (Path file : files) {
+                if (file.getFileName().toString().equals(STORED_RULES_FILE_NAME)) {
+                    continue;
+                }
+                if (Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS) && !ownedFiles.contains(fileIdentity(file))) {
+                    unownedFiles.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(unownedFiles);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private boolean repair(StoreState state, IntegrityReport report) {
+        boolean changed = false;
+        for (Entry entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                state.properties.remove(entry.description);
+                changed = true;
+            } else if (entry.resolvedViolations) {
+                deleteResolvedFile(entry.resolvedFile);
+                state.properties.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveEntryToDerivedName(state, entry);
+                state.properties.setProperty(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+        return changed;
+    }
+
+    private void moveEntryToDerivedName(StoreState state, Entry entry) {
+        Path target = safeDirectPath(state, entry.derivedName);
+        if (pathExists(target)) {
+            throw new StoreInitializationFailedException("Cannot repair occupied rule violation file " + target);
+        }
+        try {
+            if (entry.resolvedFile.path.equals(entry.resolvedFile.entryPath)) {
+                move(entry.resolvedFile.path, target, false);
+            } else {
+                move(entry.resolvedFile.path, target, false);
+                deleteIfExists(entry.resolvedFile.entryPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void deleteResolvedFile(ResolvedFile resolved) {
+        try {
+            if (!resolved.path.equals(resolved.entryPath)) {
+                deleteIfExists(resolved.entryPath);
+            }
+            delete(resolved.path);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private boolean isSharedByAnotherEntry(StoreState state, String description, ResolvedFile resolved) {
+        for (String otherDescription : state.properties.stringPropertyNames()) {
+            if (!otherDescription.equals(description)) {
+                String otherFileName = state.properties.getProperty(otherDescription);
+                if (otherFileName.equals(resolved.entryPath.getFileName().toString())) {
+                    return true;
+                }
+                ResolvedFile other = resolveEntryFile(state, otherFileName);
+                if (other != null && sameFile(resolved, other)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
+    private ResolvedFile resolveEntryFile(StoreState state, String fileName) {
+        Path entryPath = state.folder.toPath().resolve(fileName).normalize();
+        if (!isDirectPath(state, entryPath) || entryPath.getFileName().toString().equals(STORED_RULES_FILE_NAME)) {
+            return null;
+        }
+        try {
+            if (!Files.isRegularFile(entryPath)) {
+                return null;
+            }
+            Path resolvedPath = entryPath.toRealPath();
+            if (!isDirectPath(state, resolvedPath) || resolvedPath.getFileName().toString().equals(STORED_RULES_FILE_NAME)) {
+                return null;
+            }
+            return new ResolvedFile(entryPath, resolvedPath);
+        } catch (IOException e) {
+            return null;
+        }
+    }
+
+    private Path writableEntryTarget(StoreState state, String fileName) {
+        Path entryPath = safeDirectPath(state, fileName);
+        if (!pathExists(entryPath)) {
+            return entryPath;
+        }
+        ResolvedFile resolved = resolveEntryFile(state, fileName);
+        if (resolved == null) {
+            throw new StoreUpdateFailedException(new IOException("Refusing to write outside the store or over a non-file " + entryPath));
+        }
+        return resolved.path;
+    }
+
+    private Path safeDirectPath(StoreState state, String fileName) {
+        Path path = state.folder.toPath().resolve(fileName).normalize();
+        if (!isDirectPath(state, path) || path.getFileName().toString().equals(STORED_RULES_FILE_NAME)) {
+            throw new StoreUpdateFailedException(new IOException("Refusing to write outside the store or over the index: " + fileName));
+        }
+        return path;
+    }
+
+    private boolean isDirectPath(StoreState state, Path path) {
+        return state.folder.toPath().equals(path.getParent());
+    }
+
+    private boolean pathExists(Path path) {
+        return Files.exists(path, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private void delete(Path path) throws IOException {
+        if (!Files.deleteIfExists(path)) {
+            throw new NoSuchFileException(path.toString());
+        }
+    }
+
+    private void deleteIfExists(Path path) {
+        try {
+            Files.deleteIfExists(path);
+        } catch (IOException e) {
+            log.debug("Could not remove temporary store file {}", path, e);
+        }
+    }
+
+    private boolean sameFile(ResolvedFile first, ResolvedFile second) {
+        return sameFile(first.path, second.path);
+    }
+
+    private boolean sameFile(Path first, Path second) {
+        try {
+            BasicFileAttributes firstAttributes = Files.readAttributes(first, BasicFileAttributes.class);
+            BasicFileAttributes secondAttributes = Files.readAttributes(second, BasicFileAttributes.class);
+            if (firstAttributes.fileKey() != null && secondAttributes.fileKey() != null) {
+                return firstAttributes.fileKey().equals(secondAttributes.fileKey());
+            }
+            return first.toRealPath().equals(second.toRealPath());
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private String fileIdentity(Path file) {
+        try {
+            BasicFileAttributes attributes = Files.readAttributes(file, BasicFileAttributes.class);
+            if (attributes.fileKey() != null) {
+                return String.valueOf(attributes.fileKey());
+            }
+            return file.toRealPath().toString();
+        } catch (IOException e) {
+            return file.toAbsolutePath().normalize().toString();
+        }
+    }
+
+    private static Properties copyOf(Properties source) {
+        Properties result = new Properties();
+        result.putAll(source);
+        return result;
+    }
+
+    private static void writePropertiesAtomically(StoreState state, Properties properties) {
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(state.folder.toPath(), ".archunit-index-", ".tmp");
+            try (OutputStream outputStream = Files.newOutputStream(temporary)) {
+                properties.store(outputStream, "");
+            }
+            try {
+                Files.move(temporary, state.index, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+            } catch (java.nio.file.AtomicMoveNotSupportedException e) {
+                Files.move(temporary, state.index, StandardCopyOption.REPLACE_EXISTING);
+            }
+        } catch (IOException e) {
+            if (temporary != null) {
+                try {
+                    Files.deleteIfExists(temporary);
+                } catch (IOException ignored) {
